// src/utils/time-window.ts
function formatDateTime(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  const hours = String(date.getHours()).padStart(2, "0");
  const minutes = String(date.getMinutes()).padStart(2, "0");
  const seconds = String(date.getSeconds()).padStart(2, "0");
  return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
}
function getTimeWindow(now = /* @__PURE__ */ new Date()) {
  const startDate = new Date(
    now.getFullYear(),
    now.getMonth(),
    now.getDate() - 1,
    now.getHours(),
    0,
    0,
    0
  );
  const endDate = new Date(
    now.getFullYear(),
    now.getMonth(),
    now.getDate(),
    now.getHours(),
    59,
    59,
    999
  );
  return {
    startTime: formatDateTime(startDate),
    endTime: formatDateTime(endDate)
  };
}
function getTimeWindowQueryParams(now = /* @__PURE__ */ new Date()) {
  const { startTime, endTime } = getTimeWindow(now);
  return `startTime=${encodeURIComponent(startTime)}&endTime=${encodeURIComponent(endTime)}`;
}

// src/api/client.ts
var REQUEST_TIMEOUT_MS = 1e4;
async function fetchJson(url, token, queryParams) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  try {
    const fullUrl = queryParams ? `${url}?${queryParams}` : url;
    const res = await fetch(fullUrl, {
      method: "GET",
      headers: {
        Authorization: token,
        // NO "Bearer" prefix (CRITICAL)
        "Accept-Language": "en-US,en",
        "Content-Type": "application/json"
      },
      signal: controller.signal
    });
    if (!res.ok) {
      return null;
    }
    const json = await res.json();
    return json;
  } catch {
    return null;
  } finally {
    clearTimeout(timeout);
  }
}
async function fetchAllQuota(token, platform) {
  const endpoints = getEndpoints(platform);
  const queryParams = getTimeWindowQueryParams();
  const [quotaRes, modelRes, toolRes] = await Promise.allSettled([
    fetchJson(endpoints.quotaLimit, token),
    fetchJson(endpoints.modelUsage, token, queryParams),
    fetchJson(endpoints.toolUsage, token, queryParams)
  ]);
  const quotaData = quotaRes.status === "fulfilled" ? quotaRes.value : null;
  const modelData = modelRes.status === "fulfilled" ? modelRes.value : null;
  const toolData = toolRes.status === "fulfilled" ? toolRes.value : null;
  return { quotaData, modelData, toolData };
}

// src/utils/quota-parser.ts
var TOKEN_LIMIT_TYPE = "TOKENS_LIMIT";
var CREDIT_LIMIT_TYPE = "CREDIT_LIMIT";
var TIME_LIMIT_TYPE = "TIME_LIMIT";
var DEFAULT_TOKEN_LIMIT = 4e6;
function asFiniteNumber(value) {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  return null;
}
function normalizeWindowType(limit) {
  if (limit.type === CREDIT_LIMIT_TYPE) {
    return { ...limit, type: TOKEN_LIMIT_TYPE };
  }
  return limit;
}
function isFiveHourTokenLimit(limit) {
  const unit = asFiniteNumber(limit.unit);
  const number = asFiniteNumber(limit.number);
  if (limit.type === TOKEN_LIMIT_TYPE && unit === 3 && number === 5)
    return true;
  return false;
}
function isWeeklyTokenLimit(limit) {
  const unit = asFiniteNumber(limit.unit);
  const number = asFiniteNumber(limit.number);
  if (limit.type === TOKEN_LIMIT_TYPE && unit === 6 && number === 1)
    return true;
  return false;
}
function unwrapData(response) {
  if (!response) return null;
  const data = response.data;
  if (data && typeof data === "object" && !Array.isArray(data)) {
    return data;
  }
  return response;
}
function parseQuotaData(quotaResponse, modelResponse) {
  const result = {
    level: null,
    fiveHour: null,
    weekly: null,
    mcp: null,
    tokenUsed: null,
    tokenLimit: DEFAULT_TOKEN_LIMIT
  };
  const quota = unwrapData(quotaResponse);
  if (!quota) return result;
  const level = quota.level;
  if (typeof level === "string") {
    result.level = level.charAt(0).toUpperCase() + level.slice(1).toLowerCase();
  }
  const limitsRaw = quota.limits;
  if (!Array.isArray(limitsRaw)) return result;
  const limits = limitsRaw.map(normalizeWindowType);
  let tokenLimit = DEFAULT_TOKEN_LIMIT;
  let hasFiveHourMatch = false;
  for (const limit of limits) {
    if (limit.type === TOKEN_LIMIT_TYPE) {
      const percentage = asFiniteNumber(limit.percentage) ?? 0;
      const nextResetTime = asFiniteNumber(limit.nextResetTime);
      const total = asFiniteNumber(limit.total);
      if (isFiveHourTokenLimit(limit)) {
        result.fiveHour = { percentage, nextResetTime, total };
        if (total && total > 0) tokenLimit = total;
        hasFiveHourMatch = true;
      } else if (isWeeklyTokenLimit(limit)) {
        result.weekly = { percentage, nextResetTime, total };
        if (total && total > 0 && !hasFiveHourMatch) tokenLimit = total;
      }
    }
    if (limit.type === TIME_LIMIT_TYPE) {
      const percentage = asFiniteNumber(limit.percentage) ?? 0;
      const current = asFiniteNumber(limit.currentValue);
      const total = asFiniteNumber(limit.usage);
      const detailsRaw = Array.isArray(limit.usageDetails) ? limit.usageDetails : [];
      const details = detailsRaw.map((d) => ({
        modelCode: String(d.modelCode ?? d.model_code ?? "?"),
        usage: asFiniteNumber(d.usage) ?? 0
      })).filter((d) => d.modelCode !== "?");
      result.mcp = { percentage, current, total, details };
    }
  }
  if (!result.fiveHour) {
    for (const limit of limits) {
      if (limit.type === TOKEN_LIMIT_TYPE) {
        const percentage = asFiniteNumber(limit.percentage) ?? 0;
        const nextResetTime = asFiniteNumber(limit.nextResetTime);
        const total = asFiniteNumber(limit.total);
        result.fiveHour = { percentage, nextResetTime, total };
        if (total && total > 0) tokenLimit = total;
        break;
      }
    }
  }
  result.tokenLimit = tokenLimit;
  const model = unwrapData(modelResponse);
  if (model) {
    const totalUsage = model.totalUsage;
    const tokenCount = asFiniteNumber(totalUsage?.totalTokensUsage);
    if (tokenCount !== null) {
      result.tokenUsed = tokenCount;
    }
  }
  return result;
}

