// src/api/platforms.ts
function detectPlatform(providerId) {
  const lower = providerId.toLowerCase();
  if (lower.includes("zhipu") || lower.includes("bigmodel")) {
    return "ZHIPU";
  }
  if (lower.includes("zai") || lower === "z.ai" || lower === "z-ai") {
    return "ZAI";
  }
  return null;
}

// src/utils/auth.ts
var CANDIDATE_PROVIDER_IDS = [
  "zhipuai-coding-plan",
  "zai-coding-plan",
  "zai",
  "z-ai",
  "z.ai",
  "zhipu",
  "zhipuai"
];
function getAuthFilePathCandidates() {
  const homedir2 = os.homedir();
  const xdgPath = path.join(
    homedir2,
    ".local",
    "share",
    "opencode",
    "auth.json"
  );
  if (process.platform === "win32") {
    const localAppData = process.env.LOCALAPPDATA || path.join(homedir2, "AppData", "Local");
    const legacyPath = path.join(localAppData, "opencode", "auth.json");
    return [xdgPath, legacyPath];
  }
  return [xdgPath];
}
function loadSqliteSync() {
  try {
    const getBuiltinModule = process.getBuiltinModule;
    const mod = getBuiltinModule?.("node:sqlite");
    if (mod) return mod;
  } catch {
  }
  try {
    return createRequire(import.meta.url)("node:sqlite");
  } catch {
    return null;
  }
}
function getDbFilePathCandidates() {
  if (process.env.OPENCODE_DB) {
    return [process.env.OPENCODE_DB];
  }
  const dataHome = process.env.XDG_DATA_HOME || path.join(os.homedir(), ".local", "share");
  return [path.join(dataHome, "opencode", "opencode.db")];
}
function getCredentialsFromDb() {
  const sqlite = loadSqliteSync();
  if (!sqlite) return null;
  for (const dbPath of getDbFilePathCandidates()) {
    if (!fs.existsSync(dbPath)) continue;
    let db;
    try {
      db = new sqlite.DatabaseSync(dbPath, { readOnly: true });
      const rows = db.prepare(
        "SELECT integration_id, value, time_updated FROM credential WHERE active = 1"
      ).all();
      for (const providerId of CANDIDATE_PROVIDER_IDS) {
        let newest;
        for (const row of rows) {
          if (row.integration_id !== providerId) continue;
          if (!newest || row.time_updated > newest.time_updated) {
            newest = row;
          }
        }
        if (!newest) continue;
        let parsed;
        try {
          parsed = JSON.parse(newest.value);
        } catch {
          continue;
        }
        const token = extractKeyFromEntry(parsed);
        if (token) {
          const platform = detectPlatform(providerId);
          if (platform) {
            return { token, platform };
          }
        }
      }
    } catch {
    } finally {
      try {
        db?.close();
      } catch {
      }
    }
  }
  return null;
}
function extractKeyFromEntry(entry) {
  if (typeof entry === "string") return entry;
  if (typeof entry === "object" && entry !== null) {
    const obj = entry;
    for (const keyName of [
      "apiKey",
      "api_key",
      "token",
      "key",
      "accessToken",
      "auth_token"
    ]) {
      if (typeof obj[keyName] === "string") return obj[keyName];
    }
  }
  return null;
}
function getCredentials() {
  const dbCreds = getCredentialsFromDb();
  if (dbCreds) return dbCreds;
  for (const authPath of getAuthFilePathCandidates()) {
    if (!fs.existsSync(authPath)) continue;
    try {
      const content = fs.readFileSync(authPath, "utf-8");
      const authData = JSON.parse(content);
      for (const providerId of CANDIDATE_PROVIDER_IDS) {
        const entry = authData[providerId];
        if (entry) {
          const token = extractKeyFromEntry(entry);
          if (token) {
            const platform = detectPlatform(providerId);
            if (platform) {
              return { token, platform };
            }
          }
        }
      }
    } catch {
    }
  }
  if (process.env.ZAI_API_KEY) {
    return { token: process.env.ZAI_API_KEY, platform: "ZAI" };
  }
  if (process.env.ZHIPU_API_KEY || process.env.ZHIPUAI_API_KEY) {
    return {
      token: process.env.ZHIPU_API_KEY || process.env.ZHIPUAI_API_KEY,
      platform: "ZHIPU"
    };
  }
  return null;
}

