var server_default = {
  id: "opencode-glm-vistatus",
  async setup(ctx) {
    const register = ctx.rpc?.register;
    if (!register) return;
    const t = getTranslations(detectLangZH());
    let cache = null;
    const status = async () => {
      if (cache && Date.now() - cache.at < CACHE_MS) return cache.snap;
      let snap = { label: "GLM", groups: [] };
      try {
        const creds = getCredentials();
        if (creds) {
          const result = await fetchAllQuota(creds.token, creds.platform);
          const parsed = parseQuotaData(result.quotaData, result.modelData);
          const groups = [];
          if (parsed.level) {
            groups.push({ title: t.plan, value: parsed.level });
          }
          if (parsed.fiveHour) {
            groups.push({
              title: t.token5h,
              bar: quotaBar(
                parsed.fiveHour.percentage,
                parsed.fiveHour.total !== null ? Math.round(
                  parsed.fiveHour.total * parsed.fiveHour.percentage / 100
                ) : null,
                parsed.fiveHour.total
              ),
              ...withReset(parsed.fiveHour.nextResetTime)
            });
          }
          if (parsed.weekly) {
            groups.push({
              title: t.weekly,
              bar: quotaBar(
                parsed.weekly.percentage,
                parsed.weekly.total !== null ? Math.round(
                  parsed.weekly.total * parsed.weekly.percentage / 100
                ) : null,
                parsed.weekly.total
              ),
              ...withReset(parsed.weekly.nextResetTime)
            });
          }
          if (parsed.mcp) {
            groups.push({
              title: t.mcp,
              bar: quotaBar(
                parsed.mcp.percentage,
                parsed.mcp.current,
                parsed.mcp.total
              )
            });
          }
          snap = { label: "GLM", groups };
        }
      } catch {
      }
      cache = { at: Date.now(), snap };
      return snap;
    };
    for (const providerId of CANDIDATE_PROVIDER_IDS) {
      try {
        await register(
          {
            id: `${providerId}.quota`,
            methods: {
              status: {
                input: {
                  type: "object",
                  properties: {},
                  additionalProperties: false
                },
                output: { type: "object" }
              }
            },
            events: {}
          },
          { status }
        );
      } catch {
      }
    }
  }
};
